--- 新年基金

local ECSComponent = import("Frame.ECS.ECSComponent")

---@class NewYearFundComponent
local NewYearFundComponent = Class("NewYearFundComponent", ECSComponent)

function NewYearFundComponent:__init()
    self._isPay = 0   --是否支付     0, 1购买 2购买并领取
    self._drawRewards = {}   --领取过的奖励id
    self._products = {}   --商品信息
    self._signDay = 0     --签到天数 
    self._activityConf = {}
    self._uuId = 0
end

function NewYearFundComponent:__delete()
    self._isPay = 0   --是否支付
    self._drawRewards = nil   --领取过的奖励id
    self._products = nil   --商品信息
    self._signDay = 0     --签到天数 
    self._activityConf = {}
    self._uuId = 0
end

--
function NewYearFundComponent:Initial(jsonData, uuId)
    if not jsonData then
        return
    end

    self._isPay = checkNumber(jsonData.bought)
    self._drawRewards = checkTable(jsonData.drawRewards)
    self._products = checkTable(jsonData.products)
    self._signDay = checkNumber(jsonData.signDayNumber)
    self._activityConf = checkTable(jsonData.activityConf)
    self._isDrawBox = checkNumber(jsonData._isDrawBox)

    self._uuId = checkNumber(uuId)
end

function NewYearFundComponent:GetIsDrawBox()
    return (self._isPay == 2)
end

function NewYearFundComponent:GetIsPay()
    return (self._isPay >= 1)
end

function NewYearFundComponent:GetRewards()
    return self._drawRewards
end

function NewYearFundComponent:GetProducts()
    return self._products
end

function NewYearFundComponent:GetSignDay()
    return self._signDay
end

function NewYearFundComponent:GetActivityConf()
    return self._activityConf
end

function NewYearFundComponent:ActivityNewYearFundReceiveRewardReq(rewardIds, cb)
    GameUtils.Request(Interfaces.ActivityNewYearFundReceiveReward, {rewardIds = rewardIds, activityUuid = self._uuId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end

        local jsonData = response.data
        if rewardIds ~= "" then
            local t = CfUtils.Split(rewardIds, ",")
            for k, v in pairs(t) do
                table.insert(self._drawRewards, v)
            end
        else
            local NewYearFundUtils = import("Game.UI.ActivityNewYearFund.NewYearFundUtils")
            rewardIds = NewYearFundUtils.GetOneKeyDrawRewardIds(self._activityConf.id)
            local t = CfUtils.Split(rewardIds, ",")
            for k, v in pairs(t) do
                table.insert(self._drawRewards, v)
            end
        end

        local rewardList = checkTable(jsonData.rewards)
        GoodsUtils.DrawRewards(rewardList, true)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardList } })

        if cb then
            cb()
        end
    end)
end

function NewYearFundComponent:DrawBoxReq(cb)
    GameUtils.Request(Interfaces.ActivityNewYearFundReceiveBuyReward, {activityUuid = self._uuId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end

        local jsonData = response.data
        self._isPay = 2

        local rewardList = checkTable(jsonData.rewards)
        GoodsUtils.DrawRewards(rewardList, true)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardList } })

        if cb then
            cb()
        end
    end)
end

return NewYearFundComponent